function formatKstDateTime(value) {
  if (value == null || value === '') return '';
  var s = String(value).trim();
  if (/\sUTC$/.test(s)) s = s.replace(/\sUTC$/, '');   // 'YYYY-MM-DD HH:mm:ss UTC' → 라벨 제거(UTC 가정 유지)
  var iso = s;
  if (s.indexOf('T') < 0 && s.indexOf('Z') < 0 && /^\d{4}-\d{2}-\d{2}/.test(s)) {
    iso = s.replace(' ', 'T') + 'Z';          // 'YYYY-MM-DD HH:mm:ss' → UTC 가정
  } else if (s.indexOf('Z') < 0 && s.indexOf('+') < 0 && s.indexOf('T') >= 0) {
    iso = s + 'Z';                              // tz 없는 ISO → UTC 가정
  }
  var d = new Date(iso);
  if (isNaN(d.getTime())) return s.replace('T', ' ').replace('Z', '');  // 파싱 실패 → 원본(라벨 없이)
  var k = new Date(d.getTime() + 9 * 3600 * 1000);   // UTC+9 = KST
  var p = function (n) { return (n < 10 ? '0' : '') + n; };
  return k.getUTCFullYear() + '-' + p(k.getUTCMonth() + 1) + '-' + p(k.getUTCDate()) + ' '
       + p(k.getUTCHours()) + ':' + p(k.getUTCMinutes()) + ':' + p(k.getUTCSeconds()) + ' KST';
}
